// node --test .github/scripts/fenetre-verification.mjs
import { test } from "node:test";
import assert from "node:assert/strict";
import { champDuLibelle, milieu } from "./fenetre.mjs";

// La fenêtre de connexion telle que la décrit UI Automation sur la machine de GitHub
// (SimplySign Desktop 9.4.4.92, relevé du 8 octobre 2026) : aucune zone n'y dit qu'elle peut prendre la main.
const el = (nom, x, y, largeur, hauteur, classe = "STATIC", main = false) =>
  ({ nom, x, y, largeur, hauteur, main, classe: `WindowsForms10.${classe}.app.0.141b42a_r6_ad1` });
const FENETRE = [
  el("ver. 7.6.92.0", 636, 188, 100, 13),
  el("", 296, 253, 433, 17),
  el("Token generated by the SimplySign", 464, 490, 175, 13),
  el("Your e-mail address", 464, 437, 99, 13),
  el("", 295, 257, 430, 127, "Window.8"),
  el("", 295, 519, 432, 1),
  el("", 295, 390, 432, 1),
  el("Login", 292, 195, 38, 13),
  el("Cancel", 650, 524, 75, 23, "BUTTON"),
  el("Ok", 534, 524, 75, 23, "BUTTON"),
  el("", 467, 467, 258, 20, "EDIT"),
  el("Token:", 292, 469, 41, 13),
  el("", 467, 414, 258, 20, "EDIT"),
  el("ID:", 292, 416, 21, 13),
];

test("chaque champ se trouve à droite de son libellé, sur la même ligne", () => {
  assert.deepEqual(milieu(champDuLibelle(FENETRE, "ID:")), { x: 596, y: 424 });
  assert.deepEqual(milieu(champDuLibelle(FENETRE, "Token:")), { x: 596, y: 477 });
});

test("un champ sous son libellé, faute de mieux ; rien sans libellé", () => {
  const empiles = [el("ID:", 100, 100, 30, 16), el("", 100, 122, 200, 24, "EDIT"), el("Token:", 100, 160, 50, 16), el("", 100, 182, 200, 24, "EDIT")];
  assert.equal(champDuLibelle(empiles, "ID:").y, 122);
  assert.equal(champDuLibelle(empiles, "Token:").y, 182);
  assert.equal(champDuLibelle(empiles, "Mot de passe:"), null);
  assert.equal(champDuLibelle([el("ID:", 0, 0, 30, 16)], "ID:"), null);
  // Une étiquette sans nom n'est pas un champ : ni le grand cadre, ni les filets.
  assert.equal(champDuLibelle([el("ID:", 0, 0, 30, 16), el("", 40, 0, 400, 127, "Window.8"), el("", 40, 8, 400, 1)], "ID:"), null);
});
